// === BEZERRA DE ARAÚJO — POS (CORRIGIDO) ===

// 🔧 Funções auxiliares
const normalize = str => str ? str.toString().trim().toLowerCase() : '';

// ENDEREÇO
const limparEndereco = texto =>
  texto ? texto.toString().replace(/[.,;:]/g, '').trim() : '';

const limparEmail = email =>
  email ? email.toString().replace(/['"]/g, '').trim() : '';

// CEP
const formatarCEP = cep =>
  cep ? cep.toString().replace(/\D/g, '') : '';

// CPF
const formatarCPF = valor => {
  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  return `="${num.padStart(11, '0')}"`;
};

// DATA
const formatarData = data => {
  if (!data) return '';
  const s = data.toString().trim();

  if (/^\d{8}$/.test(s)) return s;

  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [dia, mes, ano] = s.split('/');
    return `${ano}${mes.padStart(2, '0')}${dia.padStart(2, '0')}`;
  }

  const d = new Date(s);
  if (isNaN(d)) return '';

  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
};

// 📞 TELEFONE (limpo)
const formatarTelefone = valor => {
  if (!valor) return '';

  const primeiro = valor.toString().split(/[\\/|;, ]/)[0].trim();
  const num = primeiro.replace(/\D/g, '');

  return num || '';
};

// 💰 VALOR — CORRIGIDO
const formatarValor = valor => {

  if (valor === null || valor === undefined || valor === '')
    return '="0,00"';

  let v = valor.toString().trim();

  // remove caracteres inválidos
  v = v.replace(/[^\d,.-]/g, '');

  // remove milhar tipo 1.234,56
  if (v.includes(',') && v.includes('.')) {
    v = v.replace(/\./g, '');
  }

  // padrão JS
  v = v.replace(',', '.');

  let num = parseFloat(v);

  if (isNaN(num)) num = 0;

  // 🔥 correção de escala
  if (num > 1000000) {
    num = num / 100;
  }

  return `="${num.toFixed(2).replace('.', ',')}"`;
};

// 🧹 Limpeza de linhas
const limparLinhas = dados =>
  dados.filter(row =>
    Object.values(row).some(v => (v || '').toString().trim() !== '')
  );

// 🔍 Input
let inputData = $input.all().map(i => i.json);

// 🧱 Processamento
let saida = inputData.map(row => ({
  'MATRICULA': row['MATRICULA'] || '',
  'NOME ALUNO': row['NOME'] || '',
  'CURSO': row['CURSO'] || '',
  'CPF': formatarCPF(row['CPF']),
  'DATA NASCIMENTO': 'NASC',
  'ENDEREÇO': limparEndereco(row['ENDERECO']),
  'BAIRRO': row['BAIRRO'] || '',
  'CIDADE': row['CIDADE'] || '',
  'CEP': formatarCEP(row['CEP']),
  'ESTADO': row['ESTADO'] || '',
  'TELEFONE': formatarTelefone(row['TELEFONE']),
  'CELULAR': formatarTelefone(row['CELULAR']),
  'RESPONSÁVEL': row['RESPONSAVEL'] || '',
  'REFERENCIA': row['REFERENCIA'] || '',
  'DATA VENCIMENTO': formatarData(row['DATA PARCELA']),
  'VALOR PARCELA': formatarValor(row['VALOR PARCEL']),
  'EMAIL': limparEmail(row['E-MAIL'])
}));

// 🔚 Retorno final
return limparLinhas(saida);
